<?php declare(strict_types=1);
require __DIR__.'/einvoice-inspection.php';
use Kulturhus\Verein\EInvoiceFields;
$sample='<Invoice xmlns="urn:oasis:names:specification:ubl:schema:xsd:Invoice-2" xmlns:cbc="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2" xmlns:cac="urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2"><cbc:ID>TEST-123</cbc:ID><cbc:IssueDate>2026-09-07</cbc:IssueDate><cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode><cac:InvoiceLine><cbc:ID>LINE-ONLY</cbc:ID></cac:InvoiceLine><cac:LegalMonetaryTotal><cbc:PayableAmount>25.00</cbc:PayableAmount></cac:LegalMonetaryTotal></Invoice>';
$fields=EInvoiceFields::read($sample);check($fields['Rechnungsnummer']==='TEST-123','root invoice number distinguished from invoice line');check($fields['Zahlbetrag laut Datei']==='25.00'&&$fields['Währung']==='EUR','payable amount and currency extracted as unverified text');check($fields['Rechnungsdatum']==='2026-09-07','invoice date extracted');check(EInvoiceFields::read(str_replace('schema:xsd:Invoice-2','schema:xsd:Fake-2',$sample))===[],'unknown root namespace not interpreted');check(EInvoiceFields::read('<!DOCTYPE i SYSTEM "file:///never"><i/>')===[],'DTD prohibited during field extraction');check(EInvoiceFields::read('<Invoice>')===[],'malformed XML not displayed');
$cii='<rsm:CrossIndustryInvoice xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100"><rsm:ExchangedDocument><ram:ID>CII-TEST</ram:ID></rsm:ExchangedDocument></rsm:CrossIndustryInvoice>';check(EInvoiceFields::read($cii)['Rechnungsnummer']==='CII-TEST','CII own document namespace recognized');$prepaid=str_replace('<cbc:PayableAmount>25.00</cbc:PayableAmount>','<cbc:TaxInclusiveAmount>119.00</cbc:TaxInclusiveAmount><cbc:PrepaidAmount>19.00</cbc:PrepaidAmount><cbc:PayableAmount>100.00</cbc:PayableAmount>',$sample);$prepaidFields=EInvoiceFields::read($prepaid);check($prepaidFields['Rechnungsbetrag brutto']==='119.00'&&$prepaidFields['Zahlbetrag laut Datei']==='100.00','prepayment leaves gross invoice amount distinct from amount due');
$duplicateGross=str_replace('<cbc:TaxInclusiveAmount>119.00</cbc:TaxInclusiveAmount>','<cbc:TaxInclusiveAmount>119.00</cbc:TaxInclusiveAmount><cbc:TaxInclusiveAmount>100.00</cbc:TaxInclusiveAmount>',$prepaid);check(EInvoiceFields::read($duplicateGross)['Rechnungsbetrag brutto']==='119.00 / 100.00','duplicate gross amounts remain visibly ambiguous, never concatenated decimals');
check(EInvoiceFields::read($prepaid)['Belegart']==='Rechnung','UBL Invoice classified by exact namespace root');
$credit=str_replace(['schema:xsd:Invoice-2','<Invoice ','</Invoice>'],['schema:xsd:CreditNote-2','<CreditNote ','</CreditNote>'],$prepaid);check(EInvoiceFields::read($credit)['Belegart']==='Gutschrift'&&EInvoiceFields::read($credit)['Rechnungsbetrag brutto']==='119.00','positive UBL credit amount remains a credit note');
$ciiInvoice=str_replace('<ram:ID>CII-TEST</ram:ID>','<ram:ID>CII-TEST</ram:ID><ram:TypeCode>380</ram:TypeCode>',$cii);check(EInvoiceFields::read($ciiInvoice)['Belegart']==='Rechnung','CII invoice requires header type 380');
check(EInvoiceFields::read(str_replace('>380<','>381<',$ciiInvoice))['Belegart']==='Gutschrift','CII credit type 381 distinguished');
check(EInvoiceFields::read($cii)['Belegart']==='Unbekannt','missing CII type not presumed invoice');
check(EInvoiceFields::read(str_replace('<ram:TypeCode>380</ram:TypeCode>','<ram:TypeCode>380</ram:TypeCode><ram:TypeCode>381</ram:TypeCode>',$ciiInvoice))['Belegart']==='Unbekannt','duplicate CII type not presumed invoice');
check(EInvoiceFields::read(str_replace('<ram:TypeCode>380</ram:TypeCode>','<TypeCode xmlns="urn:fake">380</TypeCode>',$ciiInvoice))['Belegart']==='Unbekannt','foreign type namespace cannot classify CII invoice');
$ciiGross=str_replace('</rsm:CrossIndustryInvoice>','<rsm:SupplyChainTradeTransaction><ram:ApplicableHeaderTradeSettlement><ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:GrandTotalAmount>119.00</ram:GrandTotalAmount><ram:TotalPrepaidAmount>19.00</ram:TotalPrepaidAmount><ram:DuePayableAmount>100.00</ram:DuePayableAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation></ram:ApplicableHeaderTradeSettlement></rsm:SupplyChainTradeTransaction></rsm:CrossIndustryInvoice>',$ciiInvoice);
$ciiGrossFields=EInvoiceFields::read($ciiGross);check($ciiGrossFields['Rechnungsbetrag brutto']==='119.00'&&$ciiGrossFields['Zahlbetrag laut Datei']==='100.00','CII prepaid invoice distinguishes gross and payable');
$ciiCreditFields=EInvoiceFields::read(str_replace('>380<','>381<',$ciiGross));check($ciiCreditFields['Belegart']==='Gutschrift'&&$ciiCreditFields['Rechnungsbetrag brutto']==='119.00','CII positive credit gross never makes document an invoice');
echo "$checks combined XML field checks passed\n";
